    61→        return Ok((0..number_of_custody_groups).collect::<HashSet<_>>());
    62→    }
    63→
    64→    let mut current_id = NodeId::from_be_bytes(raw_node_id);
    65→
    66→    let mut custody_groups = BTreeSet::new();
    67→    while (custody_groups.len() as u64) < custody_group_count {
    68→        let mut hasher = Sha256::new();
